import java.util.*;

public class Main {
    private static final long[] SUB = {0L, 1L, 2L, 3L, 2L, 1L};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long answer = 0L;

        if (n >= 4 && m >= 4) {
            answer = n * m;
            if ((n & 1L) != 0 && (m & 1L) != 0) {
                --answer;
            }
        } else {
            long min = Math.min(n, m);
            long max = Math.max(n, m);

            int kind = (min == 1 || min == 2 || min == 3) ? (int) min : 0;
            switch (kind) {
                case 1:
                    answer = max - SUB[(int) (max % 6)];
                    break;
                case 2:
                    if (max < 3) {
                        answer = 0L;
                    } else if (max == 3) {
                        answer = 4L;
                    } else if (max == 7) {
                        answer = 12L;
                    } else {
                        answer = 2L * max;
                    }
                    break;
                case 3:
                    if (max >= 3) {
                        answer = 3L * max;
                        if ((max & 1L) == 1L) {
                            --answer;
                        }
                    }
                    break;
                default:
                    answer = 0L;
                    break;
            }
        }

        System.out.println(answer);
    }
}
